func TestToolsManifestMatchesCodeOrchestrationCatalog(t *testing.T) {
	_, filename, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("resolve test source path")
	}
	data, err := os.ReadFile(filepath.Join(filepath.Dir(filename), "..", "..", "tools-manifest.json"))
	if err != nil {
		t.Fatalf("read tools manifest: %v", err)
	}
	var manifest struct {
		Tools []struct {
			Name   string `json:"name"`
			Method string `json:"method"`
			Path   string `json:"path"`
			Params []struct {
				Name     string `json:"name"`
				Location string `json:"location"`
				Required bool   `json:"required"`
			} `json:"params"`
		} `json:"tools"`
	}
	if err := json.Unmarshal(data, &manifest); err != nil {
		t.Fatalf("decode tools manifest: %v", err)
	}
	if len(manifest.Tools) != len(codeOrchEndpoints) {
		t.Fatalf("tools manifest contains %d endpoints, code orchestration contains %d", len(manifest.Tools), len(codeOrchEndpoints))
	}

	byName := make(map[string]codeOrchEndpoint, len(codeOrchEndpoints))
	for _, endpoint := range codeOrchEndpoints {
		byName[strings.ReplaceAll(endpoint.ID, ".", "_")] = endpoint
	}
	for _, tool := range manifest.Tools {
		endpoint, ok := byName[tool.Name]
		if !ok {
			t.Errorf("manifest tool %q has no code-orchestration endpoint", tool.Name)
			continue
		}
		if tool.Method != endpoint.Method || tool.Path != endpoint.Path {
			t.Errorf("manifest tool %q = %s %s, code orchestration = %s %s", tool.Name, tool.Method, tool.Path, endpoint.Method, endpoint.Path)
		}
		requiredPathParams := map[string]bool{}
		for _, param := range tool.Params {
			if param.Location == "path" && param.Required {
				requiredPathParams[param.Name] = true
			}
		}
		for _, positional := range endpoint.Positional {
			if !requiredPathParams[positional] {
				t.Errorf("manifest tool %q does not require path parameter %q", tool.Name, positional)
			}
			delete(requiredPathParams, positional)
		}
		for unexpected := range requiredPathParams {
			t.Errorf("manifest tool %q has unexpected required path parameter %q", tool.Name, unexpected)
		}
	}
}

func TestCodeOrchExecuteAcceptsObjectAndArrayBodiesWithoutDoubleEncoding(t *testing.T) {
	t.Setenv("HOME", t.TempDir())
	var bodies [][]byte
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Errorf("read body: %v", err)
			return
		}
		bodies = append(bodies, body)
		_, _ = io.WriteString(w, `{"ok":true}`)
	}))
	defer srv.Close()
	t.Setenv("DATAFORSEO_BASE_URL", srv.URL)

	objectBody := map[string]any{
		"keywords":      []any{"agent tools"},
		"location_code": float64(2840),
	}
	arrayBody := []any{
		map[string]any{"keywords": []any{"agent tools"}, "location_code": float64(2840)},
		map[string]any{"keywords": []any{"mcp"}, "location_code": float64(2826)},
	}

	for _, params := range []any{objectBody, arrayBody} {
		req := mcplib.CallToolRequest{Params: mcplib.CallToolParams{Arguments: map[string]any{
			"endpoint_id": "ai-optimization.ai-keyword-data-keywords-search-volume-live",
			"params":      params,
		}}}
		result, err := handleCodeOrchExecute(context.Background(), req)
		if err != nil {
			t.Fatalf("handleCodeOrchExecute: %v", err)
		}
		if result == nil || result.IsError {
			t.Fatalf("handleCodeOrchExecute result = %#v, want success", result)
		}
	}

	if len(bodies) != 2 {
		t.Fatalf("received %d request bodies, want 2", len(bodies))
	}
	for i, want := range []any{[]any{objectBody}, arrayBody} {
		var got any
		if err := json.Unmarshal(bodies[i], &got); err != nil {
			t.Fatalf("body %d is not JSON: %v; wire=%s", i, err, bodies[i])
		}
		wantJSON, _ := json.Marshal(want)
		var normalizedWant any
		_ = json.Unmarshal(wantJSON, &normalizedWant)
		if !jsonValuesEqual(got, normalizedWant) {
			t.Fatalf("body %d = %s, want %s", i, bodies[i], wantJSON)
		}
	}
	if len(bodies[0]) == 0 || bodies[0][0] != '[' {
		t.Fatalf("object body was not normalized to a task array: %s", bodies[0])
	}
	if len(bodies[1]) == 0 || bodies[1][0] != '[' {
		t.Fatalf("array body lost its top-level shape: %s", bodies[1])
	}
}

