func TestCodeOrchExecuteWritesResponseToSharedHistoryAndSearch(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("DATAFORSEO_LOGIN", "test-login")
	t.Setenv("DATAFORSEO_PASSWORD", "test-password")

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/v3/ai_optimization/ai_keyword_data/keywords_search_volume/live" {
			t.Errorf("request path = %q", r.URL.Path)
		}
		_, _ = io.WriteString(w, `{"status_code":20000,"status_message":"Ok.","tasks":[{"status_code":20000,"status_message":"Ok.","result":[{"keyword":"mcp tree service","search_volume":125}]}]}`)
	}))
	defer srv.Close()
	t.Setenv("DATAFORSEO_BASE_URL", srv.URL)

	req := mcplib.CallToolRequest{Params: mcplib.CallToolParams{Arguments: map[string]any{
		"endpoint_id": "ai-optimization.ai-keyword-data-keywords-search-volume-live",
		"params": map[string]any{
			"keywords": []any{"mcp tree service"},
		},
	}}}
	result, err := handleCodeOrchExecute(context.Background(), req)
	if err != nil {
		t.Fatalf("handleCodeOrchExecute: %v", err)
	}
	if result == nil || result.IsError {
		t.Fatalf("handleCodeOrchExecute result = %#v, want success", result)
	}

	db, err := store.Open(filepath.Join(home, ".local", "share", "dataforseo-pp-cli", "data.db"))
	if err != nil {
		t.Fatalf("open shared local store: %v", err)
	}
	defer db.Close()

	results, err := db.Search("mcp", 10)
	if err != nil {
		t.Fatalf("search shared local store: %v", err)
	}
	if len(results) != 1 || !strings.Contains(string(results[0]), "mcp tree service") {
		t.Fatalf("search results = %s, want ingested API response", results)
	}
	var historyCount int
	if err := db.DB().QueryRow(`SELECT COUNT(*) FROM resource_history WHERE resource_type = ? AND id = ?`, "ai-mentions", "mcp tree service").Scan(&historyCount); err != nil {
		t.Fatalf("query shared response history: %v", err)
	}
	if historyCount != 1 {
		t.Fatalf("shared response history count = %d, want 1", historyCount)
	}
}

